# 1. Нормализация
# =========================================================

STOP_WORDS = {
    "и", "в", "во", "на", "у", "из", "с", "со", "по", "к",
    "от", "до", "за", "при", "не", "нет", "есть", "это",
    "что", "как", "а", "но", "же", "ли", "его", "ее", "их",
    "около", "примерно", "находится", "сообщает", "сообщили",
    "может", "быть", "был", "была", "были", "уже", "ещё", "еще",
}

WEAK_WORDS = {
    "человек", "люди", "мужчина", "женщина", "ребенок", "ребенка",
    "пострадавший", "пострадавшие", "заявитель", "вызывает", "видит",
    "видел", "видела", "находятся", "находится",
}


def normalize(value):
    if value is None:
        return ""
    text = str(value).lower().replace("ё", "е")
    text = re.sub(r"[^а-яa-z0-9\s/-]", " ", text)
    text = re.sub(r"\s+", " ", text)
    return text.strip()


PHONE_RE = re.compile(
    r"(?<!\d)(?:\+?7|8)?[\s(-]*\d{3}[\s)-]*\d{3}[\s-]*\d{2}[\s-]*\d{2}(?!\d)"
)
FIO3_RE = re.compile(r"\b[А-ЯЁ][а-яё]+\s+[А-ЯЁ][а-яё]+\s+[А-ЯЁ][а-яё]+\b")
TAIL_RE = re.compile(
    r"(?i)\s*[,;]?\s*"
    r"(?:фио|заявитель|вызывает|телефон|номер телефона|звонит|очевидец|прохожий)\b"
    r"[^.]*$"
)
AM_RE = re.compile(r"\bа/м\b", re.IGNORECASE)


def clean_description(value):
    text = str(value or "")
    text = PHONE_RE.sub(" ", text)
    text = FIO3_RE.sub(" ", text)
    text = TAIL_RE.sub("", text)
    text = AM_RE.sub(" автомашина ", text)
    return re.sub(r"\s+", " ", text).strip(" ,;.")


def words(value, *, drop_weak=False):
    drop = STOP_WORDS | (WEAK_WORDS if drop_weak else set())
    return {
        w for w in normalize(value).split()
        if (len(w) >= 2 or w.isdigit()) and w not in drop
    }


def word_stem(word):
    return word[:5] if len(word) >= 5 else word


def stem_set(value, *, drop_weak=False):
    return {word_stem(w) for w in words(value, drop_weak=drop_weak)}


def load_json(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


# 2. Чтение билетов
def get_ticket_list(data):
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in ("tickets", "билеты", "items", "data"):
            if isinstance(data.get(key), list):
                return data[key]
    raise ValueError("Не удалось найти список билетов в tickets.json")


def get_situations(ticket):
    if not isinstance(ticket, dict):
        return []
    for key in ("situations", "ситуации", "incidents", "cases"):
        value = ticket.get(key)
        if isinstance(value, list):
            return value
    return []


def get_description(situation):
    if isinstance(situation, str):
        return clean_description(situation)
    if not isinstance(situation, dict):
        return clean_description(situation)
    for key in ("description", "Описание", "text", "текст", "situation"):
        v = situation.get(key)
        if v:
            return clean_description(v)
    excluded = {
        "address", "адрес", "phone", "телефон",
        "name", "фио", "caller_name", "caller_phone",
    }
    parts = [
        str(v) for k, v in situation.items()
        if isinstance(v, str) and k.lower() not in excluded
    ]
    return clean_description(" ".join(parts))


def get_ticket_number(ticket, index):
    if isinstance(ticket, dict):
        for key in ("ticket_number", "number", "номер", "ticket_id", "id"):
            if ticket.get(key) is not None:
                return ticket[key]
    return index + 1


