# 5. Работа с классификатором
def prepare_incidents(classifier_data):
    if isinstance(classifier_data, list):
        incidents = classifier_data
    elif isinstance(classifier_data, dict):
        incidents = (
            classifier_data.get("incidents")
            or classifier_data.get("data")
        )
    else:
        incidents = None
    if not isinstance(incidents, list):
        raise ValueError("Не удалось извлечь список инцидентов из классификатора.")
    return [it for it in incidents if isinstance(it, dict)]


def incident_code(incident):
    return str(
        incident.get("number") or incident.get("code")
        or incident.get("id") or "unknown"
    )


def incident_name(incident):
    return str(
        incident.get("incident_type")
        or incident.get("ekp35_type")
        or incident.get("group")
        or incident.get("category")
        or "Без названия"
    )


INCIDENT_TEXT_FIELDS = (
    "category", "group", "incident_type", "ekp35_type",
    "main_service", "additional_features",
)


def incident_text(incident):
    parts = [str(incident.get(f) or "") for f in INCIDENT_TEXT_FIELDS]
    features = incident.get("features") or []
    if isinstance(features, list):
        parts.extend(str(x) for x in features)
    else:
        parts.append(str(features))
    return normalize(" ".join(parts))


