def incident_event_type(incident):
    label = normalize(incident_name(incident))
    for event, hints in CATEGORY_HINTS:
        if any(hint in label for hint in hints):
            return event
    primary, _ = detect_events(label)
    return primary


# =========================================================
# 6. Скоринг
# =========================================================

def keyword_overlap(description, incident):
    d = stem_set(description, drop_weak=True)
    c = stem_set(incident_text(incident), drop_weak=True)
    return float(len(d & c))


def sequence_ratio(description, incident):
    a = normalize(description)
    b = incident_text(incident)
    if not a or not b:
        return 0.0
    return SequenceMatcher(None, a, b).ratio()


